#include <cstdlib>
#include <fstream>
#include <iostream>
#include <map>
#include <sstream>
#include <string>
#include <vector>
using namespace std;

static string translate(const map<string, string>& dict, const string& content) {
    ostringstream os;
    string word;
    string s = content;
    s += '\n';  // 与参考程序一致：结尾补一个非字母触发收尾
    for (size_t i = 0; i < s.size(); ++i) {
        if (s[i] >= 'a' && s[i] <= 'z') {
            word += s[i];
        } else {
            if (!word.empty()) {
                map<string, string>::const_iterator it = dict.find(word);
                if (it != dict.end()) os << it->second;
                else os << "UNK";
                word.clear();
            }
            os << s[i];
        }
    }
    string r = os.str();
    if (!r.empty() && r.back() == '\n') r.pop_back();
    return r;
}
static bool check(const string& exe, const vector<pair<string, string>>& dictRows, const string& content, int id) {
    const string inF = "l4a12p1_in.txt", outF = "l4a12p1_out.txt";
    {
        ofstream o(inF);
        o << dictRows.size() << '\n';
        for (size_t i = 0; i < dictRows.size(); ++i) o << dictRows[i].first << ' ' << dictRows[i].second << '\n';
        o << content << '\n';
    }
    int code = system(("\"" + exe + "\" < " + inF + " > " + outF + " 2>/dev/null").c_str());
    ifstream in(outF);
    string actual((istreambuf_iterator<char>(in)), istreambuf_iterator<char>());
    if (!actual.empty() && (actual.back() == '\n' || actual.back() == '\r')) actual.pop_back();
    map<string, string> dict;
    for (size_t i = 0; i < dictRows.size(); ++i) dict[dictRows[i].first] = dictRows[i].second;
    string want = translate(dict, content);
    if (code != 0 || actual != want) {
        cout << "[FAIL] case " << id << ": expected=" << want
             << ", actual=" << actual.substr(0, 200) << ", status=" << code << '\n';
        return false;
    }
    return true;
}
int main(int argc, char* argv[]) {
    if (argc < 2) return 2;
    const string exe = argv[1];
    int passed = 0, total = 0;
    ++total;
    if (check(exe, {{string("abc"), string("a")}, {string("d"), string("def")}}, "abc.d.d.abc.abcd.", 1)) ++passed;  // 样例1
    ++total;
    if (check(exe, {{string("abc"), string("a")}, {string("d"), string("def")}, {string("abcd"), string("xxxx")}}, "abc,(d)d!-abc?abcd", 2)) ++passed;  // 样例2
    ++total;
    if (check(exe, {{string("abcdefghij"), string("klmnopqrst")}}, "!()-[]{}\\;\'\"\,./?><abcdefghijklmnopqrstuvwxyz", 3)) ++passed;  // 样例3
    // 边界：单词在结尾（依赖补换行收尾）、全 UNK、长文随机
    srand(20231201);
    for (int t = 0; t < 5; ++t) {
        int n = 1 + rand() % 100;
        vector<pair<string, string>> rows;
        for (int i = 0; i < n; ++i) {
            string a, b;
            int la = 1 + rand() % 10, lb = 1 + rand() % 10;
            for (int k = 0; k < la; ++k) a += char('a' + rand() % 26);
            for (int k = 0; k < lb; ++k) b += char('a' + rand() % 26);
            rows.push_back(make_pair(a, b));
        }
        string content;
        int len = 100 + rand() % 900;
        for (int k = 0; k < len; ++k) {
            if (rand() % 10 < 6) content += char('a' + rand() % 26);
            else content += "()[],.-!?'\"/\\<>;: "[(rand() % 16)];
        }
        if (rand() % 2) content += string("abc");  // 有时以未闭合单词结尾
        ++total;
        if (check(exe, rows, content, 4 + t)) ++passed;
    }
    cout << "Results: " << passed << "/" << total << " passed" << '\n';
    return passed == total ? 0 : 1;
}

